-- Dev/test-only staff accounts for the seed venue (The Racquet Club Sukhumvit 49).
-- Both sign in at POST /api/v1/auth/staff/login (ClubOS login page) with password: racquet-dev-2026
-- Existing local databases: apply once with
--   docker compose exec -T db psql -U bkktennis -d bkktennis -v ON_ERROR_STOP=1 < db/init/004_seed_staff.sql
-- Hashes are generated by pgcrypto (bcrypt, cost 10) so nothing secret-looking is committed.

UPDATE users
SET email = 'owner@racquetclub.test', password_hash = crypt('racquet-dev-2026', gen_salt('bf', 10))
WHERE id = '00000000-0000-0000-0000-000000000002';

